documents.rows:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, SEQ]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  HOME: {path: home.csv, types: {SEQ: int, DAY: int}}
  REF: {path: ref.csv, types: {REFDAY: int}}
  WIN: {path: win.csv, types: {LO: int, HI: int}, key: [STUDYID]}
  CAL: {path: cal.csv, types: {CALDY: int}}
output: {path: out.csv, columns: [STUDYID, USUBJID, SEQ, W]}
intermediates:
  - {id: RK, dataset: REF, key: [STUDYID, USUBJID]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: SEQ, type: int}
  - {name: ADAY, type: int}
  - {name: W, type: str}
rows:
  - id: clinic
    dataset: CLINIC
    derivations:
      STUDYID: CLINIC.STUDYID
      USUBJID: CLINIC.USUBJID
      SEQ: CLINIC.SEQ
      ADAY: CLINIC.DAY
  - id: home
    dataset: HOME
    derivations:
      STUDYID: HOME.STUDYID
      USUBJID: HOME.USUBJID
      SEQ: HOME.SEQ
      ADAY: HOME.DAY

documents.base:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, SEQ]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  REF: {path: ref.csv, types: {REFDAY: int}}
  WIN: {path: win.csv, types: {LO: int, HI: int}, key: [STUDYID]}
  CAL: {path: cal.csv, types: {CALDY: int}}
base: CLINIC
output: {path: out.csv, columns: [STUDYID, USUBJID, SEQ, W]}
intermediates:
  - {id: RK, dataset: REF, key: [STUDYID, USUBJID]}
columns:
  - {name: STUDYID, type: str, derivation: CLINIC.STUDYID}
  - {name: USUBJID, type: str, derivation: CLINIC.USUBJID}
  - {name: SEQ, type: int, derivation: CLINIC.SEQ}
  - {name: ADAY, type: int, derivation: CLINIC.DAY}
  - {name: W, type: str, derivation: WI.NAME}

documents.donor:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, SEQ]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  REF: {path: ref.csv, types: {REFDAY: int}}
  OTHER: {path: other.csv, types: {OTHDAY: int}}
  WIN: {path: win.csv, types: {LO: int, HI: int}}
base: CLINIC
output: {path: out.csv, columns: [STUDYID, USUBJID, SEQ, W]}
intermediates:
  - {id: RK, dataset: OTHER, key: [STUDYID, USUBJID]}
  - {id: WI, dataset: WIN, key: [STUDYID], between: {value: REFDAY, lower: LO, upper: HI}}
  - {id: D, dataset: REF, key: [STUDYID, USUBJID], derivations: {WNAME: WI.NAME}}
columns:
  - {name: STUDYID, type: str, derivation: CLINIC.STUDYID}
  - {name: USUBJID, type: str, derivation: CLINIC.USUBJID}
  - {name: SEQ, type: int, derivation: CLINIC.SEQ}
  - {name: W, type: str, derivation: D.WNAME}

documents.dosed:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, ASEQ]
input:
  SUBJ: {path: subjects.csv, types: {EXSTDT: date}}
  EX: {path: ex.csv, types: {EXSEQ: int, EXDOSE: int, EXSTDT: date}}
  PERIODS: {path: periods.csv, types: {APERIOD: int, APERSDT: date, APEREDT: date}, key: [STUDYID, USUBJID]}
output: {path: out.csv, columns: [STUDYID, USUBJID, ASEQ, APERIOD]}
intermediates:
  - {id: DOSED, dataset: EX, filter: "EX.EXDOSE > 0"}
  - {id: W, dataset: PERIODS, key: [STUDYID, USUBJID], between: {value: DOSED.EXSTDT, lower: APERSDT, upper: APEREDT}, order_by: [PERIODS.APERIOD], keep: first}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: ASEQ, type: int}
  - {name: APERIOD, type: int}
rows:
  - id: dosed
    dataset: DOSED
    derivations: {STUDYID: DOSED.STUDYID, USUBJID: DOSED.USUBJID, ASEQ: DOSED.EXSEQ, APERIOD: null}
  - id: subject
    dataset: SUBJ
    derivations: {STUDYID: SUBJ.STUDYID, USUBJID: SUBJ.USUBJID, ASEQ: 0, APERIOD: null}

edits.to:
- {id: RK, dataset: REF, key: [STUDYID, USUBJID]}
- {id: WI, dataset: WIN, key: {STUDYID: STUDYID, LO: RK.REFDAY}}
- {id: D, dataset: REF, key: [STUDYID, USUBJID], derivations: {WNAME: WI.NAME}}
